/**
 * Why a Bash command touches the archive, or null.
 *
 * @param {string} command
 * @param {string} cwd
 */
function bashTouches(command, cwd) {
  let here = cwd
  for (const c of parseCommands(command)) {
    if (c.name === 'cd' || c.name === 'pushd') {
      const to = c.args.find(a => !a.startsWith('-'))
